    "path": {"$ref": "#/definitions/Path"},
    "createdMs": {"type": "integer", "minimum": 0}
   }
  },
  "Answer": {
   "description": "Written by the answering server into its own store at v1/fleet/exchange/<from>/answers/<id>.json, after its body <id>.bin; `sha256` and `size` describe the body (absent without a body).",
   "type": "object",
   "additionalProperties": false,
   "required": ["version", "id", "status", "atMs"],
   "properties": {
    "version": {"const": 1},
    "id": {"type": "string", "pattern": "^[0-9a-f]{24}$"},
    "status": {"type": "integer", "minimum": 100, "maximum": 599},
    "size": {"type": "integer", "minimum": 0},
